func requireSandbox(instance *blaxel.SandboxInstance, operation string) (*blaxel.Sandbox, error) {
	if instance == nil || instance.Sandbox == nil {
		return nil, invalidResponse(operation, sandboxInfoFieldID(), "SDK returned no sandbox")
	}
	return instance.Sandbox, nil
}

func sandboxInfoFieldID() string {
	// Kept as a tiny indirection so instance.go stays free of a sandbox import
	// cycle risk if helpers move; callers use the shared field constant.
	return "id"
}

