// processRequest builds the Blaxel Process.New body. Timeout 0 disables
// Blaxel's default auto-kill. WaitForCompletion is only set for 1–60s.
func processRequest(command string, timeout time.Duration, request *sandbox.ExecOptions) blaxel.ProcessRequestParam {
	body := blaxel.ProcessRequestParam{
		Command:           command,
		Timeout:           blaxel.Int(int64(timeout / time.Second)),
		WaitForCompletion: blaxel.Bool(completionHold(timeout)),
	}
	if request.WorkingDirectory != nil {
		body.WorkingDir = blaxel.String(*request.WorkingDirectory)
	}
	if request.Environment != nil {
		body.Env = request.Environment
	}
	return body
}

// finishProcess returns a terminal start response as-is. Otherwise it polls
// with Process.Wait — including when waitForCompletion was true but the status
// is still running. Wait retries gateway 504; cancel/deadline become
// Canceled/Timeout.
func finishProcess(
	ctx context.Context,
	instance *blaxel.SandboxInstance,
	started *blaxel.ProcessResponse,
	timeout time.Duration,
) (*sandbox.ExecResult, error) {
	if started == nil || processFinished(started) {
		return execResult(started)
	}
	identifier := processIdentifier(started)
	if identifier == "" {
		return nil, sandbox.NewError(&sandbox.ErrorInfo{
			Kind:      sandbox.ErrorKindInvalidResponse,
			Provider:  "blaxel",
			Operation: "run",
			Message:   "sandbox-kit blaxel: SDK returned no process identifier",
		}, nil)
	}
	finished, err := instance.Process.Wait(ctx, identifier, waitBudget(timeout), processPollInterval)
	if err != nil {
		return nil, mapProviderError(err, "run")
	}
	return execResult(finished)
}

