func planCreate(request *sandbox.CreateOptions, region string) (blaxel.SandboxNewParams, error) {
	if request == nil {
		request = &sandbox.CreateOptions{}
	}
	if err := validateProviderCreate(request); err != nil {
		return blaxel.SandboxNewParams{}, err
	}
	if region == "" {
		return blaxel.SandboxNewParams{}, providerCheckError(sandbox.ErrorKindInvalidArgument, sandbox.ConfigFieldRegion, "Config.Region is required")
