import {
  SandboxInstance,
  settings,
  type Config as NativeClientConfig,
  type SandboxCreateConfiguration,
  type SandboxCreateOptions,
} from "@blaxel/core";
import type { BlaxelSandboxIdentity } from "#mappings/provider_mappings.js";

export interface BlaxelProcessResult {
  readonly pid?: string;
  readonly name?: string;
  readonly status?: string;
  readonly exitCode?: number;
  readonly stdout?: string;
  readonly stderr?: string;
}

export interface ProcessExecRequest {
  command: string;
  waitForCompletion?: boolean;
  timeout?: number;
  workingDir?: string;
  env?: Record<string, string>;
}

export interface NativeSandboxHandle extends BlaxelSandboxIdentity {
  readonly fs: {
    readBinary(path: string): Promise<Blob>;
    writeBinary(path: string, content: Uint8Array): Promise<unknown>;
    mkdir(path: string, permissions?: string): Promise<unknown>;
    ls(path: string): Promise<import("@blaxel/core").Directory>;
    rm(path: string, recursive?: boolean): Promise<unknown>;
    download(src: string, destinationPath: string): Promise<void>;
  };
  readonly process: {
    exec(request: ProcessExecRequest): Promise<BlaxelProcessResult>;
    wait(
      identifier: string,
      options?: {
        maxWait?: number;
        interval?: number;
        signal?: AbortSignal;
      },
    ): Promise<BlaxelProcessResult>;
  };
  delete(): Promise<unknown>;
}

export interface NativeBlaxel {
  configure(config: NativeClientConfig): void;
  create(
    params: SandboxCreateConfiguration,
    options?: SandboxCreateOptions,
  ): Promise<NativeSandboxHandle>;
  get(name: string): Promise<NativeSandboxHandle>;
  delete(name: string): Promise<unknown>;
}

export type NativeFactory = (config: NativeClientConfig) => NativeBlaxel;

export function defaultNativeFactory(config: NativeClientConfig): NativeBlaxel {
  settings.setConfig(config);
  return {
    configure(next: NativeClientConfig): void {
      settings.setConfig(next);
    },
    create(params, options) {
      return SandboxInstance.create(params, options);
    },
    get(name) {
      return SandboxInstance.get(name);
    },
    delete(name) {
      return SandboxInstance.delete(name);
    },
  };
}

import { mkdir, readFile, stat } from "node:fs/promises";
import { dirname } from "node:path";

import {
  ErrorKind,
  FileFieldLocalPath,
  SandboxError,
  sandboxError,
} from "@sandbox-kit/sandbox";
import { providerError } from "./errors.js";

/** Rejects a missing local file or a directory before Blaxel reads it. */
export async function requireLocalFile(
  localPath: string,
  operation: string,
): Promise<void> {
  let info;
  try {
    info = await stat(localPath);
  } catch (error) {
    if (nodeCode(error)) throw localFileError(error, operation);
    throw error;
  }
  if (info.isDirectory()) localDirectory(operation);
}

/** Rejects a local destination that is already a directory. */
export async function requireLocalDestination(
  localPath: string,
  operation: string,
): Promise<void> {
  try {
    const info = await stat(localPath);
    if (info.isDirectory()) localDirectory(operation);
  } catch (error) {
    if (nodeCode(error) === "ENOENT") return;
    if (nodeCode(error)) throw localFileError(error, operation);
    throw error;
  }
}

/** Creates the parent directory for a local destination path. */
export async function ensureLocalParent(
  localPath: string,
  operation: string,
): Promise<void> {
  try {
    await mkdir(dirname(localPath), { recursive: true });
  } catch (error) {
    throw localFileError(error, operation);
  }
}

/** Reads a local file for upload into the sandbox. */
export async function readLocalFile(
  localPath: string,
  operation: string,
): Promise<Uint8Array> {
  await requireLocalFile(localPath, operation);
  try {
    return await readFile(localPath);
  } catch (error) {
    throw localFileError(error, operation);
  }
}

function localDirectory(operation: string): never {
  providerError({
    kind: ErrorKind.InvalidArgument,
    operation,
    field: FileFieldLocalPath,
    message: "local path is a directory",
  });
}

function localFileError(error: unknown, operation: string): SandboxError {
  return sandboxError(
    {
      kind:
        nodeCode(error) === "ENOENT"
          ? ErrorKind.NotFound
          : ErrorKind.InvalidArgument,
      provider: "blaxel",
      operation,
      field: FileFieldLocalPath,
      message: error instanceof Error ? error.message : "local path failed",
    },
    error,
  );
}

function nodeCode(error: unknown): string | undefined {
  if (typeof error !== "object" || !error || !("code" in error))
    return undefined;
  return typeof error.code === "string" ? error.code : undefined;
}

import {
  ErrorKind,
  ExecFieldTimeout,
  sandboxError,
  type ExecOptions,
  type ExecResult,
} from "@sandbox-kit/sandbox";
import { providerError } from "./errors.js";
import type {
  BlaxelProcessResult,
  NativeSandboxHandle,
  ProcessExecRequest,
} from "./native.js";

/** Blaxel's documented limit for a single waitForCompletion request. */
const blaxelCompletionHoldSeconds = 60;

const terminalProcessStatus = new Set([
  "completed",
  "failed",
  "killed",
  "stopped",
]);

export function processRequest(
  request: ExecOptions,
  timeout: number | undefined,
): ProcessExecRequest {
  return {
    command: blaxelCommand(request),
    // 1–60s can use Blaxel's completion hold; omit/0/longer timeouts poll.
    waitForCompletion: holdsCompletion(timeout),
    // omit/0 → 0 disables Blaxel's default process auto-kill.
    timeout: timeout ?? 0,
    ...(request.workingDirectory === undefined
      ? {}
      : { workingDir: request.workingDirectory }),
    ...(request.environment === undefined
      ? {}
      : { env: { ...request.environment } }),
  };
}

export async function finishProcess(
  process: NativeSandboxHandle["process"],
  started: BlaxelProcessResult,
  timeout: number | undefined,
  signal: AbortSignal | undefined,
): Promise<ExecResult> {
  if (processFinished(started.status)) return execResult(started);
  const identifier = started.pid || started.name;
  if (!identifier) {
    throw sandboxError({
      kind: ErrorKind.InvalidResponse,
      provider: "blaxel",
      operation: "run",
      field: "",
      message: "sandbox-kit blaxel: SDK returned no process identifier",
    });
  }
  const finished = await process.wait(identifier, {
    maxWait: timeout === undefined ? -1 : timeout * 1_000,
    interval: 1_000,
    ...(signal === undefined ? {} : { signal }),
  });
  return execResult(finished);
}

/**
 * Maps Kit ExecOptions.timeout (ms) to Blaxel seconds.
 * Omitted and explicit zero become undefined so the caller sends 0 (no limit).
 */
export function execTimeoutSeconds(
  timeout: number | undefined,
): number | undefined {
  if (timeout === undefined || timeout === 0) return undefined;
  if (!Number.isFinite(timeout) || timeout < 0 || timeout % 1_000 !== 0) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "run",
      field: ExecFieldTimeout,
      message: "timeout must be a whole number of seconds",
    });
  }
  return timeout / 1_000;
}

function holdsCompletion(timeoutSeconds: number | undefined): boolean {
  return (
    timeoutSeconds !== undefined &&
    timeoutSeconds > 0 &&
    timeoutSeconds <= blaxelCompletionHoldSeconds
  );
}

function processFinished(status: string | undefined): boolean {
  return status !== undefined && terminalProcessStatus.has(status);
}

function execResult(result: BlaxelProcessResult): ExecResult {
  return {
    exitCode: result.exitCode ?? 0,
    stdout: new TextEncoder().encode(result.stdout ?? ""),
    stderr: new TextEncoder().encode(result.stderr ?? ""),
  };
}

function blaxelCommand(request: ExecOptions): string {
  if (request.shell !== undefined) return request.shell;
  return posixShellJoin(request.argv ?? []);
}

function posixShellJoin(argv: readonly string[]): string {
  return argv.map(posixQuote).join(" ");
}

function posixQuote(value: string): string {
  if (value === "") return "''";
  return "'" + value.replaceAll("'", `'"'"'`) + "'";
}

import { basename, dirname } from "node:path";
import type { Directory, File as BlaxelFile } from "@blaxel/core";
import {
  ErrorKind,
  FileFieldPath,
  FileType,
  sandboxError,
  type FileInfo,
} from "@sandbox-kit/sandbox";
import type { NativeSandboxHandle } from "./native.js";

type BlaxelSubdirectory = Directory["subdirectories"][number];

export function fileInfo(info: BlaxelFile): FileInfo {
  const modified = Date.parse(info.lastModified);
  return {
    name: info.name,
    path: info.path,
    type: FileType.File,
    size: BigInt(Math.trunc(info.size)),
    ...(info.permissions ? { permissions: info.permissions } : {}),
    ...(info.owner ? { owner: info.owner } : {}),
    ...(info.group ? { group: info.group } : {}),
    ...(Number.isNaN(modified) ? {} : { modifiedAt: new Date(modified) }),
  };
}

export function directoryInfo(info: BlaxelSubdirectory): FileInfo {
  return {
    name: info.name,
    path: info.path,
    type: FileType.Directory,
    size: 0n,
  };
}

/** Blaxel has no Stat; ls wraps GET and rejects file paths with this error. */
export async function blaxelStat(
  fs: NativeSandboxHandle["fs"],
  path: string,
): Promise<FileInfo> {
  try {
    const listing = await fs.ls(path);
    return {
      name: listing.name || basename(path) || "/",
      path: listing.path || path,
      type: FileType.Directory,
      size: 0n,
    };
  } catch (error) {
    if (!isBlaxelFilePath(error)) throw error;
  }
  const parent = dirname(path);
  const name = basename(path);
  const listing = await fs.ls(parent === "." ? "/" : parent);
  const file = listing.files.find((entry) => entry.name === name);
  if (file) return fileInfo(file);
  throw sandboxError({
    kind: ErrorKind.NotFound,
    provider: "blaxel",
    operation: "stat",
    field: FileFieldPath,
    message: `sandbox-kit blaxel: path not found: ${path}`,
  });
}

/** Blaxel `fs.ls` throws this when GET returns a file instead of a directory. */
function isBlaxelFilePath(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  try {
    const body = JSON.parse(error.message) as { error?: unknown };
    return body.error === "Directory not found";
  } catch {
    return false;
  }
}

// Native Blaxel error translation is handwritten.
// Classification order: existing SandboxError, abort/timeout DOMException,
// then Blaxel helpers / ResponseError status, then unknown.
// Cause stays on SandboxError.cause.

import {
  CredentialsError,
  getBlaxelErrorCode,
  getBlaxelErrorStatus,
  isCreationTimeoutError,
  isGatewayError,
  isGatewayTimeout,
  ResponseError,
  SandboxCreationTimeoutError,
  SandboxGatewayError,
} from "@blaxel/core";
import {
  ErrorKind,
  SandboxError,
  sandboxError,
  type ErrorInfo,
} from "@sandbox-kit/sandbox";

/** Inputs for translating a native/provider failure into {@link SandboxError}. */
interface MappedErrorInput {
  kind: ErrorInfo["kind"];
  error: unknown;
  operation: string;
  statusCode?: number;
  providerCode?: string;
}

/** Inputs for throwing a Blaxel-scoped validation or mapping error. */
export interface ProviderErrorInput {
  kind: ErrorInfo["kind"];
  operation: string;
  field: string;
  message: string;
}

const CODE_KINDS: Record<string, ErrorInfo["kind"]> = {
  AUTHENTICATION_REQUIRED: ErrorKind.Authentication,
  AUTHENTICATION_FAILED: ErrorKind.Authentication,
  TOKEN_REVOKED: ErrorKind.Authentication,
  FORBIDDEN: ErrorKind.PermissionDenied,
  UNAUTHORIZED: ErrorKind.PermissionDenied,
  UNAUTHORIZED_WORKSPACE: ErrorKind.PermissionDenied,
  ROUTE_NOT_FOUND: ErrorKind.NotFound,
  WORKLOAD_NOT_FOUND: ErrorKind.NotFound,
  WORKSPACE_NOT_FOUND: ErrorKind.NotFound,
  IMAGE_NOT_FOUND: ErrorKind.NotFound,
  VOLUME_NOT_FOUND: ErrorKind.NotFound,
  ACCOUNT_NOT_FOUND: ErrorKind.NotFound,
  SANDBOX_DELETED: ErrorKind.NotFound,
  VOLUME_DELETED: ErrorKind.NotFound,
  SANDBOX_ALREADY_EXISTS: ErrorKind.AlreadyExists,
  VOLUME_ALREADY_ATTACHED: ErrorKind.AlreadyExists,
  BAD_REQUEST: ErrorKind.InvalidArgument,
  POLICY_VIOLATION: ErrorKind.InvalidArgument,
  INVALID_INPUT: ErrorKind.InvalidArgument,
  INVALID_IMAGE: ErrorKind.InvalidArgument,
  INVALID_PORTS: ErrorKind.InvalidArgument,
  INVALID_REGION: ErrorKind.InvalidArgument,
  INVALID_VOLUME: ErrorKind.InvalidArgument,
  INVALID_VOLUME_COUNT: ErrorKind.InvalidArgument,
  INVALID_VOLUME_REGION: ErrorKind.InvalidArgument,
  VALIDATION_FAILED: ErrorKind.InvalidArgument,
  VALIDATION_ERROR: ErrorKind.InvalidArgument,
  WORKSPACE_REQUIRED: ErrorKind.InvalidArgument,
  CREATION_TIMEOUT: ErrorKind.Timeout,
  UPSTREAM_CONNECT_TIMEOUT: ErrorKind.Timeout,
  UPSTREAM_TIMEOUT: ErrorKind.Timeout,
  QUOTA_EXCEEDED: ErrorKind.ResourceExhausted,
  USAGE_LIMIT_EXCEEDED: ErrorKind.ResourceExhausted,
  RATE_LIMIT_EXCEEDED: ErrorKind.RateLimited,
  WORKSPACE_RATE_LIMIT_EXCEEDED: ErrorKind.RateLimited,
  SANDBOX_DELETION_IN_PROGRESS: ErrorKind.Conflict,
  WORKLOAD_UNAVAILABLE: ErrorKind.Unavailable,
  ROUTING_UNAVAILABLE: ErrorKind.Unavailable,
  SERVICE_UNAVAILABLE: ErrorKind.Unavailable,
  AUTHENTICATION_UNAVAILABLE: ErrorKind.Unavailable,
  UPSTREAM_CONNECT_FAILED: ErrorKind.Unavailable,
  UPSTREAM_ERROR: ErrorKind.Unavailable,
  GATEWAY_INTERNAL_ERROR: ErrorKind.Unavailable,
  WORKLOAD_FAILED: ErrorKind.Internal,
  INTERNAL_ERROR: ErrorKind.Internal,
  HANDLER_ERROR: ErrorKind.Internal,
  DATABASE_ERROR: ErrorKind.Internal,
};

const STATUS_KINDS: Record<number, ErrorInfo["kind"]> = {
  400: ErrorKind.InvalidArgument,
  422: ErrorKind.InvalidArgument,
  401: ErrorKind.Authentication,
  402: ErrorKind.ResourceExhausted,
  403: ErrorKind.PermissionDenied,
  404: ErrorKind.NotFound,
  410: ErrorKind.NotFound,
  408: ErrorKind.Timeout,
  409: ErrorKind.Conflict,
  412: ErrorKind.FailedPrecondition,
  429: ErrorKind.RateLimited,
  500: ErrorKind.Internal,
  502: ErrorKind.Unavailable,
  503: ErrorKind.Unavailable,
  504: ErrorKind.Timeout,
};

export function mapBlaxelError(
  error: unknown,
  operation: string,
): SandboxError {
  if (error instanceof SandboxError) return error;
  if (error instanceof DOMException && error.name === "AbortError")
    return create({ kind: ErrorKind.Canceled, error, operation });
  if (error instanceof DOMException && error.name === "TimeoutError")
    return create({ kind: ErrorKind.Timeout, error, operation });

  const cause = causeOf(error);
  let kind: ErrorInfo["kind"] = ErrorKind.Unknown;
  const statusCode =
    getBlaxelErrorStatus(error) ?? getBlaxelErrorStatus(cause);
  const providerCode = stringifyCode(
    getBlaxelErrorCode(error) ?? getBlaxelErrorCode(cause),
  );

  if (error instanceof CredentialsError) kind = ErrorKind.Authentication;
  if (
    kind === ErrorKind.Unknown &&
    (error instanceof SandboxCreationTimeoutError ||
      isCreationTimeoutError(error))
  )
    kind = ErrorKind.Timeout;
  // process.wait deadline is a plain Error; a 504 on one poll may be its cause.
  // A bare edge 504 is a timeout too, matching Go.
  if (
    kind === ErrorKind.Unknown &&
    (isProcessWaitTimeout(error) ||
      isGatewayTimeout(error) ||
      isGatewayTimeout(cause))
  )
    kind = ErrorKind.Timeout;
  if (
    kind === ErrorKind.Unknown &&
    (error instanceof SandboxGatewayError || isGatewayError(error))
  )
    kind = ErrorKind.Unavailable;

  if (kind === ErrorKind.Unknown && providerCode !== undefined)
    kind = CODE_KINDS[providerCode] ?? ErrorKind.Unknown;
  if (kind === ErrorKind.Unknown && statusCode !== undefined)
    kind = STATUS_KINDS[statusCode] ?? ErrorKind.Unknown;
  if (
    kind === ErrorKind.Unknown &&
    error instanceof ResponseError &&
    error.status !== undefined
  )
    kind = STATUS_KINDS[error.status] ?? ErrorKind.Unknown;

  return create({
    kind,
    error,
    operation,
    ...(statusCode === undefined ? {} : { statusCode }),
    ...(providerCode === undefined ? {} : { providerCode }),
  });
}

function isProcessWaitTimeout(error: unknown): boolean {
  return (
    error instanceof Error &&
    error.message.startsWith("Process did not finish in time")
  );
}

function causeOf(error: unknown): unknown {
  return error instanceof Error ? error.cause : undefined;
}

function stringifyCode(code: unknown): string | undefined {
  if (typeof code === "string" && code !== "") return code;
  if (typeof code === "number") return String(code);
  return undefined;
}

function create(input: MappedErrorInput): SandboxError {
  const { kind, error, operation, statusCode, providerCode } = input;
  return sandboxError(
    {
      kind,
      provider: "blaxel",
      operation,
      field: "",
      message:
        error instanceof Error
          ? error.message
          : "sandbox-kit blaxel: provider operation failed",
      ...(statusCode === undefined ? {} : { statusCode }),
      ...(providerCode === undefined ? {} : { providerCode }),
    },
    error,
  );
}

/** Local throw helper for mappings, checks, and config. */
export function providerError(input: ProviderErrorInput): never {
  throw sandboxError({
    kind: input.kind,
    provider: "blaxel",
    operation: input.operation,
    field: input.field,
    message: "sandbox-kit blaxel: " + input.message,
  });
}

