	result, err := fn(instance.FS)
	if err != nil {
		// Preserve SandboxErrors raised inside the callback (e.g. list mapping).
		var local *sandbox.Error
		if errors.As(err, &local) {
			return zero, err
		}
		return zero, mapProviderError(err, call.Operation)
	}
