import {
  ErrorKind,
  ExecFieldTimeout,
  sandboxError,
  type ExecOptions,
  type ExecResult,
} from "@sandbox-kit/sandbox";
import { providerError } from "./errors.js";
import type {
  BlaxelProcessResult,
  NativeSandboxHandle,
  ProcessExecRequest,
} from "./native.js";

/** Blaxel's documented limit for a single waitForCompletion request. */
const blaxelCompletionHoldSeconds = 60;

const terminalProcessStatus = new Set([
  "completed",
  "failed",
  "killed",
  "stopped",
]);

export function processRequest(
  request: ExecOptions,
  timeout: number | undefined,
): ProcessExecRequest {
  const body: ProcessExecRequest = {
    command: blaxelCommand(request),
    // 1–60s can use Blaxel's completion hold; omit/0/longer timeouts poll.
    waitForCompletion: holdsCompletion(timeout),
    // omit/0 → 0 disables Blaxel's default process auto-kill.
    timeout: timeout ?? 0,
  };
  if (request.workingDirectory !== undefined) {
    body.workingDir = request.workingDirectory;
  }
  if (request.environment !== undefined) {
    body.env = { ...request.environment };
  }
  return body;
}

/** Internal wait orchestration after Process.exec. */
export interface FinishProcessArgs {
  process: NativeSandboxHandle["process"];
  started: BlaxelProcessResult;
  timeout: number | undefined;
  signal: AbortSignal | undefined;
}

export async function finishProcess(
  args: FinishProcessArgs,
): Promise<ExecResult> {
  if (processFinished(args.started.status)) return execResult(args.started);
  const identifier = args.started.pid || args.started.name;
  if (!identifier) {
    throw sandboxError({
      kind: ErrorKind.InvalidResponse,
      provider: "blaxel",
      operation: "run",
      field: "",
      message: "sandbox-kit blaxel: SDK returned no process identifier",
    });
  }
  const waitOptions: {
    maxWait: number;
    interval: number;
    signal?: AbortSignal;
  } = {
    maxWait: args.timeout === undefined ? -1 : args.timeout * 1_000,
    interval: 1_000,
  };
  if (args.signal !== undefined) waitOptions.signal = args.signal;
  return execResult(await args.process.wait(identifier, waitOptions));
}

/**
 * Maps Kit ExecOptions.timeout (ms) to Blaxel seconds.
 * Omitted and explicit zero become undefined so the caller sends 0 (no limit).
 */
export function execTimeoutSeconds(
  timeout: number | undefined,
): number | undefined {
  if (timeout === undefined || timeout === 0) return undefined;
  if (!isWholeSecondTimeout(timeout)) {
    providerError({
      kind: ErrorKind.InvalidArgument,
      operation: "run",
      field: ExecFieldTimeout,
      message: "timeout must be a whole number of seconds",
    });
  }
  return timeout / 1_000;
}

function isWholeSecondTimeout(timeout: number): boolean {
  return Number.isFinite(timeout) && timeout >= 0 && timeout % 1_000 === 0;
}

function holdsCompletion(timeoutSeconds: number | undefined): boolean {
  return (
    timeoutSeconds !== undefined &&
    timeoutSeconds > 0 &&
    timeoutSeconds <= blaxelCompletionHoldSeconds
  );
}

function processFinished(status: string | undefined): boolean {
  return status !== undefined && terminalProcessStatus.has(status);
}

function execResult(result: BlaxelProcessResult): ExecResult {
  return {
    exitCode: result.exitCode ?? 0,
    stdout: new TextEncoder().encode(result.stdout ?? ""),
    stderr: new TextEncoder().encode(result.stderr ?? ""),
  };
}

function blaxelCommand(request: ExecOptions): string {
  if (request.shell !== undefined) return request.shell;
  return posixShellJoin(request.argv ?? []);
}

function posixShellJoin(argv: readonly string[]): string {
  return argv.map(posixQuote).join(" ");
}

function posixQuote(value: string): string {
  if (value === "") return "''";
  return "'" + value.replaceAll("'", `'"'"'`) + "'";
}

import {
  ErrorKind,
  FileFieldParents,
  SandboxState,
  type FileInfo,
  type OperationOptions,
  type Provider,
  type SandboxInfo,
} from "@sandbox-kit/sandbox";
import type {
  Backend,
  Config,
  CreateOptions,
  CreateResult,
  DeleteOptions,
  ExecOptions,
  ExecResult,
  FileCopyOptions,
  FileReadOptions,
  FileWriteOptions,
  ListDirectoryOptions,
  MakeDirectoryOptions,
  RemoveOptions,
  StatOptions,
} from "@sandbox-kit/sandbox";
import {
  mapClientConfig,
  mapCreateRequest,
  mapSandboxInfo,
} from "#mappings/mappings.js";
import { mapBlaxelError, providerError } from "#errors.js";
import { BackendBase, ProviderBase } from "./provider.js";
import {
  captureProviderState,
  type ProviderState,
} from "#config/provider_config.js";
import { blaxelStat, directoryInfo, fileInfo } from "./filesystem.js";
import {
  ensureLocalParent,
  readLocalFile,
  requireLocalDestination,
} from "./local.js";
import {
  defaultNativeFactory,
  type NativeBlaxel,
  type NativeFactory,
  type NativeSandboxHandle,
} from "./native.js";
import {
  execTimeoutSeconds,
  finishProcess,
  processRequest,
} from "./process.js";

/** @internal Exported for adapter boundary tests, but not from the package root. */
export class BlaxelProvider extends ProviderBase {
  constructor(
    private readonly nativeFactory: NativeFactory = defaultNativeFactory,
  ) {
    super();
  }

  initialize(config: Config): Backend {
    try {
      const nativeConfig = mapClientConfig(config);
      const native = this.nativeFactory(nativeConfig);
      native.configure(nativeConfig);
      return new BlaxelBackend(native, captureProviderState(config));
    } catch (error) {
      throw mapBlaxelError(error, "initialize");
    }
  }
}

interface WithSandboxArgs<T> {
  operation: string;
  id: string;
  options: OperationOptions;
  body: (sandbox: NativeSandboxHandle) => Promise<T>;
}

class BlaxelBackend extends BackendBase implements Backend {
  constructor(
    private readonly native: NativeBlaxel,
    private readonly config: ProviderState,
  ) {
    super();
  }

  async create(
    request: CreateOptions,
    options: OperationOptions,
  ): Promise<CreateResult> {
    try {
      throwIfAborted(options.signal);
      const plan = mapCreateRequest(request, this.config);
      throwIfAborted(options.signal);
      const sandbox = await this.native.create(plan.params, plan.options);
      return { sandbox: mapSandboxInfo(sandbox, request) };
    } catch (error) {
      throw mapBlaxelError(error, "create");
    }
  }

  async refresh(id: string, options: OperationOptions): Promise<SandboxInfo> {
    return this.#withSandbox({
      operation: "refresh",
      id,
      options,
      body: async (sandbox) => mapSandboxInfo(sandbox),
    });
  }

  async delete(
    id: string,
    _request: DeleteOptions,
    options: OperationOptions,
  ): Promise<SandboxInfo> {
    return this.#withSandbox({
      operation: "delete",
      id,
      options,
      body: async (sandbox) => {
        const info = mapSandboxInfo(sandbox);
        await sandbox.delete();
        return {
          ...info,
          state: SandboxState.Deleted,
          terminal: true,
          providerState: "TERMINATED",
        };
      },
    });
  }

  async readFile(
    id: string,
    path: string,
    _request: FileReadOptions,
    options: OperationOptions,
  ): Promise<Uint8Array> {
    return this.#withSandbox({
      operation: "read_file",
      id,
      options,
      body: async (sandbox) => {
        const blob = await sandbox.fs.readBinary(path);
        return new Uint8Array(await blob.arrayBuffer());
      },
    });
  }

  async writeFile(
    id: string,
    path: string,
    data: Uint8Array,
    _request: FileWriteOptions,
    options: OperationOptions,
  ): Promise<void> {
    await this.#withSandbox({
      operation: "write_file",
      id,
      options,
      body: async (sandbox) => {
        await sandbox.fs.writeBinary(path, data);
      },
    });
  }

  async copyFromLocal(
    id: string,
    localPath: string,
    remotePath: string,
    _request: FileCopyOptions,
    options: OperationOptions,
  ): Promise<void> {
    const data = await readLocalFile(localPath, "copy_from_local");
    await this.#withSandbox({
      operation: "copy_from_local",
      id,
      options,
      body: async (sandbox) => {
        await sandbox.fs.writeBinary(remotePath, data);
      },
    });
  }

  async copyToLocal(
    id: string,
    remotePath: string,
    localPath: string,
    _request: FileCopyOptions,
    options: OperationOptions,
  ): Promise<void> {
    await requireLocalDestination(localPath, "copy_to_local");
    await ensureLocalParent(localPath, "copy_to_local");
    await this.#withSandbox({
      operation: "copy_to_local",
      id,
      options,
      body: async (sandbox) => {
        await sandbox.fs.download(remotePath, localPath);
      },
    });
  }

  async makeDirectory(
    id: string,
    path: string,
    request: MakeDirectoryOptions,
    options: OperationOptions,
  ): Promise<void> {
    if (request.parents === false) {
      providerError({
        kind: ErrorKind.Unsupported,
        operation: "make_directory",
        field: FileFieldParents,
        message: "parents false is not available",
      });
    }
    await this.#withSandbox({
      operation: "make_directory",
      id,
      options,
      body: async (sandbox) => {
        await sandbox.fs.mkdir(path);
      },
    });
  }

  async listDirectory(
    id: string,
    path: string,
    _request: ListDirectoryOptions,
    options: OperationOptions,
  ): Promise<FileInfo[]> {
    return this.#withSandbox({
      operation: "list_directory",
      id,
      options,
      body: async (sandbox) => {
        const listing = await sandbox.fs.ls(path);
        return [
          ...listing.subdirectories.map((entry) => directoryInfo(entry)),
          ...listing.files.map((entry) => fileInfo(entry)),
        ];
      },
    });
  }

  async stat(
    id: string,
    path: string,
    _request: StatOptions,
    options: OperationOptions,
  ): Promise<FileInfo> {
    return this.#withSandbox({
      operation: "stat",
      id,
      options,
      body: async (sandbox) => blaxelStat(sandbox.fs, path),
    });
  }

  async remove(
    id: string,
    path: string,
    request: RemoveOptions,
    options: OperationOptions,
  ): Promise<void> {
    await this.#withSandbox({
      operation: "remove",
      id,
      options,
      body: async (sandbox) => {
        await sandbox.fs.rm(path, request.recursive === true);
      },
    });
  }

  async run(
    id: string,
    request: ExecOptions,
    options: OperationOptions,
  ): Promise<ExecResult> {
    return this.#withSandbox({
      operation: "run",
      id,
      options,
      body: async (sandbox) => {
        const timeout = execTimeoutSeconds(request.timeout);
        const started = await sandbox.process.exec(
          processRequest(request, timeout),
        );
        return finishProcess({
          process: sandbox.process,
          started,
          timeout,
          signal: options.signal,
        });
      },
    });
  }

  async #withSandbox<T>(args: WithSandboxArgs<T>): Promise<T> {
    try {
      throwIfAborted(args.options.signal);
      const sandbox = await this.native.get(args.id);
      throwIfAborted(args.options.signal);
      return await args.body(sandbox);
    } catch (error) {
      throw mapBlaxelError(error, args.operation);
    }
  }

  async closeSandbox(_id: string, _options: OperationOptions): Promise<void> {}

  async close(options: OperationOptions): Promise<void> {
    throwIfAborted(options.signal);
  }
}

function throwIfAborted(signal: AbortSignal | undefined): void {
  signal?.throwIfAborted();
}

/**
 * Selects Blaxel as the provider for the shared Sandbox Kit client.
 *
 * Create needs `name`, an image source, and client `region`. Set
 * `auth.apiKey` and `scope.workspace`, or omit them so `@blaxel/core` can use
 * `BL_API_KEY` / `BL_WORKSPACE`. `memoryMib` maps 1:1 onto Blaxel's memory
 * field; Kit has no portable volume fields. `@blaxel/core` stores credentials
 * in process-global `settings` — use one Blaxel Kit client, or one credential
 * set, per process.
 */
export function blaxel(): Provider {
  return new BlaxelProvider();
}

